[CmdletBinding()]
param([string]$Root = "C:\Users\adams\OneDrive\Documents\SprintTimerIntegrated")
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
Set-Location -LiteralPath $Root
$Root = (Get-Location).Path
function Closed {
    if (Get-Process -Name SprintTimerIntegrated -ErrorAction SilentlyContinue) {
        throw "Close SprintTimerIntegrated completely before running this patch."
    }
}
function Replace-One([string]$Text,[string]$Old,[string]$New) {
    if ([regex]::Matches($Text,[regex]::Escape($Old)).Count -ne 1) {
        throw "Expected exactly one anchor: $Old"
    }
    return $Text.Replace($Old,$New)
}
function Normal([string]$Text) { return $Text.Replace("`r`n","`n") }
Closed
$expected = "1c1d6ecb2580d8a36662aff8167d9df672c6d048"
$head = (& git rev-parse HEAD | Out-String).Trim()
if ($LASTEXITCODE -ne 0 -or $head -ne $expected) { throw "Unexpected Git HEAD; nothing changed." }
$names = @("Program.cs","Vision.cs","LiveRecovery.cs","Overlay.cs","CaptureDiagnostics.cs","Settings.cs","FocusGuard.cs","Build.ps1")
$assets = @("SDL2.dll","icon.png","detector.json","settings.json")
$exe = "SprintTimerIntegrated.exe"
$inputNames = @($names + $assets + $exe)
$hashes = @{}
foreach ($name in $inputNames) {
    $path = Join-Path $Root $name
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing $name" }
    $hashes[$name] = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
}
# Compare live source to the reviewed commit, allowing line-ending conversion only.
foreach ($name in $names) {
    $committed = @(& git show "$($expected):$name")
    if ($LASTEXITCODE -ne 0) { throw "Cannot inspect committed $name" }
    $live = Normal ([IO.File]::ReadAllText((Join-Path $Root $name)))
    if ($live.TrimEnd("`n") -cne (($committed -join "`n").TrimEnd("`n"))) {
        throw "$name has unreviewed local changes. Nothing changed."
    }
}
$stage = Join-Path $env:TEMP ("SprintTimer-reminder-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $stage | Out-Null
foreach ($name in ($names + $assets)) {
    Copy-Item -LiteralPath (Join-Path $Root $name) -Destination (Join-Path $stage $name)
}
$utf8 = New-Object Text.UTF8Encoding($false)
$program = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
[IO.File]::WriteAllText((Join-Path $stage "Program.cs"),$program,$utf8)
$overlayPath = Join-Path $stage "Overlay.cs"
$overlay = Normal ([IO.File]::ReadAllText($overlayPath))
$overlay = Replace-One $overlay 'double threshold = (double)reminderSeconds.Value;' 'double threshold = EffectiveReminderSeconds;'
$overlay = Replace-One $overlay 'footer = "Reminder disabled";' 'footer = reminderMode.SelectedIndex == 1 && !RankReminderValid ? "Invalid warning lead - check settings" : "Reminder disabled";'
[IO.File]::WriteAllText($overlayPath,$overlay,$utf8)
$settingsPath = Join-Path $stage "Settings.cs"
$settings = Normal ([IO.File]::ReadAllText($settingsPath))
$old = '                RestoreNumber(data, "reminder_seconds", reminderSeconds);'
$new = @'
                RestoreNumber(data, "reminder_seconds", reminderSeconds);
                swiftRank.SelectedIndex = ReadSettingInt(data, "swift_start_rank", 5, 1, 5) - 1;
                RestoreNumber(data, "warning_lead_seconds", warningLead);
                reminderMode.SelectedIndex = ReadSettingInt(data, "reminder_mode", 0, 0, 1);
                RefreshRankReminder();
'@
$settings = Replace-One $settings $old (Normal $new)
$old = '        data["reminder_seconds"] = reminderSeconds.Value;'
$new = @'
        data["reminder_seconds"] = reminderSeconds.Value;
        data["reminder_mode"] = reminderMode.SelectedIndex;
        data["swift_start_rank"] = swiftRank.SelectedIndex + 1;
        data["warning_lead_seconds"] = warningLead.Value;
'@
$settings = Replace-One $settings $old (Normal $new)
$old = '        // Do not save an unconfirmed replacement for a missing monitor.'
$new = @'
        if (reminderMode.SelectedIndex == 1 && !RankReminderValid)
        {
            e.Cancel = true;
            MessageBox.Show(this,
                "Warn before must be shorter than the selected rank estimate. " +
                "Correct it or select Manual before closing.",
                "Invalid reminder settings", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        // Do not save an unconfirmed replacement for a missing monitor.
'@
$settings = Replace-One $settings $old (Normal $new)
[IO.File]::WriteAllText($settingsPath,$settings,$utf8)
$tokens = $null; $parseErrors = $null
$null = [Management.Automation.Language.Parser]::ParseFile((Join-Path $stage "Build.ps1"),[ref]$tokens,[ref]$parseErrors)
if ($parseErrors.Count -gt 0) { throw ($parseErrors | Out-String) }
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $stage "Build.ps1") -Root $stage -NoLaunch
if ($LASTEXITCODE -ne 0) { throw "Staged build failed. Installed files untouched. Stage: $stage" }
$built = Join-Path $stage $exe
if (-not (Test-Path -LiteralPath $built)) { throw "No staged EXE." }
if (([Diagnostics.FileVersionInfo]::GetVersionInfo($built)).FileVersion -ne "0.2.15.0") { throw "Wrong staged EXE version." }
Closed
foreach ($name in $inputNames) {
    if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $hashes[$name]) {
        throw "$name changed while building; nothing installed. Stage: $stage"
    }
}
$backup = Join-Path $Root ("backup-reminder-v0.2.15-" + (Get-Date -Format yyyyMMdd-HHmmss) + "-" + [guid]::NewGuid().ToString("N").Substring(0,8))
New-Item -ItemType Directory -Path $backup | Out-Null
foreach ($name in $inputNames) {
    $dest = Join-Path $backup $name
    Copy-Item -LiteralPath (Join-Path $Root $name) -Destination $dest
    if ((Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash -ne $hashes[$name]) { throw "Backup mismatch: $name" }
}
$install = @("Program.cs","Overlay.cs","Settings.cs",$exe)
$touched = New-Object 'System.Collections.Generic.List[string]'
try {
    foreach ($name in $install) {
        $touched.Add($name)
        Copy-Item -LiteralPath (Join-Path $stage $name) -Destination (Join-Path $Root $name) -Force
        if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne
            (Get-FileHash -LiteralPath (Join-Path $stage $name) -Algorithm SHA256).Hash) { throw "Install mismatch: $name" }
    }
}
catch {
    $failure = $_
    foreach ($name in $touched) {
        try {
            Copy-Item -LiteralPath (Join-Path $backup $name) -Destination (Join-Path $Root $name) -Force
            if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $hashes[$name]) { throw "Hash mismatch" }
        } catch { Write-Warning "ROLLBACK FAILED: $name. Restore from $backup. $_" }
    }
    throw $failure
}
Write-Host "BUILD AND INSTALL SUCCEEDED: Sprint Timer v0.2.15 (x64)" -ForegroundColor Green
Write-Host "Verified backup: $backup"
Write-Host "EXE version: $(([Diagnostics.FileVersionInfo]::GetVersionInfo((Join-Path $Root $exe))).FileVersion)"
Write-Host "EXE SHA256: $((Get-FileHash -LiteralPath (Join-Path $Root $exe) -Algorithm SHA256).Hash)"
Write-Host "Existing settings.json retained; Manual mode remains the migration default. No Git writes performed."
Start-Process -FilePath (Join-Path $Root $exe) -WorkingDirectory $Root -ErrorAction Stop
Write-Host "Launch requested. Confirm v0.2.15 in the running GUI."
